css:
    
        body {
            font-family: sans-serif;
            margin: 20px;
            padding: 20px;
        }
        table {
            width: 100%;
            border-collapse: collapse;
        }
        
        td, th {
            border: 1px solid #000;
            padding: 8px;
            text-align: left;
            font-size: 12px;
        }
        .main-table {
            border: 1px solid #000;
        }
        .header-cell {
            /*text-align: center;*/
            /*vertical-align: top;*/
            padding: 0;
            border: none;
        }
        .logo-container {
            text-align: center;
            padding: 10px;
        }
        .logo-container img {
            max-width: 100px;
        }
        .title-cell {
            font-size: 20px;
            font-weight: bold;
            text-align: center;
            padding-top: 20px;
            vertical-align: top;
        }
        .details-label {
            font-weight: bold;
            background-color: #f2f2f2;
            width: 15%;
        }
        .details-value {
            width: 20%;
        }
        .requisition-header {
            background-color: #007bff;
            color: white;
            text-align: center;
            font-weight: bold;
            padding: 10px;
        }
        .requisition-subheader th {
            background-color: #007bff;
            color: white;
            text-align: center;
            font-size: 12px;
            padding: 10px;
        }

        .approval-cell {
            vertical-align: top;
            padding: 10px;
        }
        .approval-cell-half {
            width: 50%;
        }
        .signature-line {
            border-bottom: 1px solid #000;
            margin-top: 5px;
            height: 1px;
        }
        .signature-label {
            font-weight: bold;
            margin-bottom: 5px;
        }
